<!-- wp:group {"tagName":"section","align":"full","className":"m-hero","layout":{"type":"constrained"}} --><section class="wp-block-group alignfull m-hero"><!-- wp:group {"align":"wide","className":"hero-grid","layout":{"type":"default"}} --><div class="wp-block-group alignwide hero-grid"><!-- wp:group {"className":"hero-text","layout":{"type":"default"}} --><div class="wp-block-group hero-text"><!-- wp:heading {"level":1,"className":"hero-title"} --><h1 class="wp-block-heading hero-title">Let your light shine.</h1><!-- /wp:heading --><!-- wp:paragraph {"className":"lead"} --><p class="lead">M516 is a Christ-centered ministry designed to reach the corners of the earth with the redeeming message of the Gospel for all people.</p><!-- /wp:paragraph --><!-- wp:buttons --><div class="wp-block-buttons"><!-- wp:button {"className":"is-style-light"} --><div class="wp-block-button is-style-light"><a class="wp-block-button__link wp-element-button" href="/booking/">Book your next event</a></div><!-- /wp:button --><!-- wp:button {"className":"is-style-text"} --><div class="wp-block-button is-style-text"><a class="wp-block-button__link wp-element-button" href="/about/">Learn more about M516</a></div><!-- /wp:button --></div><!-- /wp:buttons --></div><!-- /wp:group --><!-- wp:image {"className":"hero-photo"} --><figure class="wp-block-image hero-photo"><img src="https://the516movement.com/wp-content/uploads/2015/08/Falls-Creek-2023-3.jpg" alt="Ryan Young preaching to students at Falls Creek"/></figure><!-- /wp:image --></div><!-- /wp:group --></section><!-- /wp:group -->
<!-- wp:group {"tagName":"section","align":"full","className":"m-section m-intro","layout":{"type":"constrained"}} --><section class="wp-block-group alignfull m-section m-intro"><!-- wp:quote {"className":"scripture is-large"} --><blockquote class="wp-block-quote scripture is-large"><!-- wp:paragraph --><p>In the same way, let your light shine before others, that they may see your good deeds and glorify your Father in heaven.</p><!-- /wp:paragraph --><cite>Matthew 5:16</cite></blockquote><!-- /wp:quote --><!-- wp:paragraph {"className":""} --><p class="">This is the core concept of The 516 Movement. We want to see a movement of God unlike anything we have ever seen before. If followers of Christ would live a Matthew 5:16 life, we believe that revival would break out.</p><!-- /wp:paragraph --><!-- wp:paragraph {"className":""} --><p class="">We need to not just pray for revival, we need to live for revival.</p><!-- /wp:paragraph --></section><!-- /wp:group -->
<!-- wp:group {"tagName":"section","align":"full","className":"m-section is-paper","layout":{"type":"constrained"}} --><section class="wp-block-group alignfull m-section is-paper"><!-- wp:group {"align":"wide","className":"trio-wrap","layout":{"type":"default"}} --><div class="wp-block-group alignwide trio-wrap"><!-- wp:heading {"level":2,"className":"section-title"} --><h2 class="wp-block-heading section-title">Ministry, missions, movement</h2><!-- /wp:heading --><!-- wp:columns {"className":"trio"} --><div class="wp-block-columns trio"><!-- wp:column --><div class="wp-block-column"><!-- wp:heading {"level":3,"className":""} --><h3 class="wp-block-heading ">Ministry</h3><!-- /wp:heading --><!-- wp:paragraph {"className":""} --><p class="">The spiritual work or service of any Christian or a group of Christians, especially evangelism.</p><!-- /wp:paragraph --></div><!-- /wp:column --><!-- wp:column --><div class="wp-block-column"><!-- wp:heading {"level":3,"className":""} --><h3 class="wp-block-heading ">Missions</h3><!-- /wp:heading --><!-- wp:paragraph {"className":""} --><p class="">The calling of a Christian organization to go into the world and spread its faith.</p><!-- /wp:paragraph --></div><!-- /wp:column --><!-- wp:column --><div class="wp-block-column"><!-- wp:heading {"level":3,"className":""} --><h3 class="wp-block-heading ">Movement</h3><!-- /wp:heading --><!-- wp:paragraph {"className":""} --><p class="">A group of people working together to advance their shared ideas.</p><!-- /wp:paragraph --></div><!-- /wp:column --></div><!-- /wp:columns --><!-- wp:paragraph {"className":"trio-note"} --><p class="trio-note">We would love to show your students or congregation how to effectively minister to others, to live a lifestyle of missions, and to join the movement of the Holy Spirit in this world. <a href="/our-values/">Read our values</a></p><!-- /wp:paragraph --></div><!-- /wp:group --></section><!-- /wp:group -->
<!-- wp:group {"tagName":"section","align":"full","className":"m-section","layout":{"type":"constrained"}} --><section class="wp-block-group alignfull m-section"><!-- wp:group {"align":"wide","className":"editorial","layout":{"type":"default"}} --><div class="wp-block-group alignwide editorial"><!-- wp:image {"className":"editorial__photo"} --><figure class="wp-block-image editorial__photo"><img src="https://the516movement.com/wp-content/uploads/2015/08/Family-Photo-2023-2.jpg" alt="Ryan Young with his wife Karistin and their children, Annslee and Cross"/></figure><!-- /wp:image --><!-- wp:group {"className":"editorial__body","layout":{"type":"default"}} --><div class="wp-block-group editorial__body"><!-- wp:heading {"level":2,"className":"section-title"} --><h2 class="wp-block-heading section-title">Meet Ryan Young</h2><!-- /wp:heading --><!-- wp:paragraph {"className":""} --><p class="">Ryan has surrendered his life to Jesus Christ. He is married to his amazing wife, Karistin. They have a beautiful daughter, Annslee, and a handsome son, Cross.</p><!-- /wp:paragraph --><!-- wp:paragraph {"className":""} --><p class="">He has served in student ministry for 20 years and has led mission teams locally, nationally and internationally. Missions isn’t just an international concept. Where there are people, there are mission opportunities.</p><!-- /wp:paragraph --><!-- wp:paragraph {"className":"more"} --><p class="more"><a href="/about-ryan/">More about Ryan</a></p><!-- /wp:paragraph --></div><!-- /wp:group --></div><!-- /wp:group --></section><!-- /wp:group -->
<!-- wp:group {"tagName":"section","align":"full","className":"m-section is-paper","layout":{"type":"constrained"}} --><section class="wp-block-group alignfull m-section is-paper"><!-- wp:group {"align":"wide","className":"gallery-wrap","layout":{"type":"default"}} --><div class="wp-block-group alignwide gallery-wrap"><!-- wp:heading {"level":2,"className":"section-title"} --><h2 class="wp-block-heading section-title">Ministry in action</h2><!-- /wp:heading --><!-- wp:group {"align":"wide","className":"photo-grid","layout":{"type":"default"}} --><div class="wp-block-group alignwide photo-grid"><!-- wp:image {"className":"p1"} --><figure class="wp-block-image p1"><img src="https://the516movement.com/wp-content/uploads/2015/08/Falls-Creek-2023-2-2.jpg" alt="Worship at Falls Creek"/><figcaption class="wp-element-caption">Worship at Falls Creek</figcaption></figure><!-- /wp:image --><!-- wp:image {"className":"p2"} --><figure class="wp-block-image p2"><img src="https://the516movement.com/wp-content/uploads/2015/08/Japan-2023-2-2.jpg" alt="Mission trip to Japan"/><figcaption class="wp-element-caption">Mission trip to Japan</figcaption></figure><!-- /wp:image --><!-- wp:image {"className":"p3"} --><figure class="wp-block-image p3"><img src="https://the516movement.com/wp-content/uploads/2015/08/Duncan-2025-2.jpg" alt="Duncan, Oklahoma"/><figcaption class="wp-element-caption">Duncan, Oklahoma</figcaption></figure><!-- /wp:image --></div><!-- /wp:group --></div><!-- /wp:group --></section><!-- /wp:group -->
<!-- wp:group {"tagName":"section","align":"full","className":"m-section m-answer","layout":{"type":"constrained"}} --><section class="wp-block-group alignfull m-section m-answer"><!-- wp:heading {"level":2,"className":"section-title"} --><h2 class="wp-block-heading section-title">Jesus is the answer</h2><!-- /wp:heading --><!-- wp:paragraph {"className":""} --><p class="">Putting your faith in Jesus Christ is the most important decision that you will ever make.</p><!-- /wp:paragraph --><!-- wp:quote {"className":"scripture"} --><blockquote class="wp-block-quote scripture"><!-- wp:paragraph --><p>I am the way, the truth, and the life. No one comes to the Father except through me.</p><!-- /wp:paragraph --><cite>John 14:6</cite></blockquote><!-- /wp:quote --><!-- wp:paragraph {"className":"more"} --><p class="more"><a href="/the-answer/">Read The Answer</a> &nbsp;·&nbsp; <a href="/armor-up/">Armor Up, a daily prayer</a></p><!-- /wp:paragraph --></section><!-- /wp:group -->
<!-- wp:group {"tagName":"section","align":"full","className":"m-band","layout":{"type":"constrained"}} --><section class="wp-block-group alignfull m-band"><!-- wp:group {"align":"wide","className":"band","layout":{"type":"default"}} --><div class="wp-block-group alignwide band"><!-- wp:heading {"level":2,"className":"band__title"} --><h2 class="wp-block-heading band__title">Bring M516 to your church, camp, or event</h2><!-- /wp:heading --><!-- wp:paragraph {"className":""} --><p class="">Even if Ryan isn’t available, he may be able to recommend someone who would be perfect for your event. He will do everything he can to work within your budget.</p><!-- /wp:paragraph --><!-- wp:buttons --><div class="wp-block-buttons"><!-- wp:button {"className":"is-style-light"} --><div class="wp-block-button is-style-light"><a class="wp-block-button__link wp-element-button" href="/booking/">Book your next event</a></div><!-- /wp:button --><!-- wp:button {"className":"is-style-text"} --><div class="wp-block-button is-style-text"><a class="wp-block-button__link wp-element-button" href="/donate/">Support the ministry</a></div><!-- /wp:button --></div><!-- /wp:buttons --></div><!-- /wp:group --></section><!-- /wp:group -->
